
"use client";

import React, { Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { PartyPopper } from 'lucide-react';

function DinSuccessContent() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const din = searchParams.get('din');

    if (!din) {
        return (
            <Card className="w-full max-w-lg mx-auto">
                <CardHeader className='text-center'>
                    <CardTitle className='text-destructive'>Error</CardTitle>
                </CardHeader>
                <CardContent className="text-center space-y-4">
                    <p className="text-muted-foreground">Could not retrieve your DIN. Please check your profile or applications page.</p>
                </CardContent>
                 <CardFooter className="flex justify-center">
                    <Button onClick={() => router.push('/dashboard/my-applications')}>
                        View My Applications
                    </Button>
                </CardFooter>
            </Card>
        )
    }

    return (
        <Card className="w-full max-w-lg mx-auto">
            <CardHeader className='text-center'>
                <PartyPopper className="mx-auto h-12 w-12 text-green-500" />
                <CardTitle className='text-primary'>Application Complete!</CardTitle>
            </CardHeader>
            <CardContent className="text-center space-y-4">
                 <p className="text-muted-foreground">Your application was submitted successfully and your DIN has been generated.</p>
                <div className="p-4 bg-muted rounded-lg">
                    <p className="text-sm text-muted-foreground">Your Developer Identification Number is:</p>
                    <p className="text-2xl font-bold tracking-widest text-primary">{din}</p>
                </div>
            </CardContent>
            <CardFooter className="flex justify-center">
                <Button onClick={() => router.push('/dashboard/my-applications')}>
                    View My Applications
                </Button>
            </CardFooter>
        </Card>
    );
}


export default function DinApplicationSuccessPage() {
    return (
        <div className="container mx-auto px-2 sm:px-4 py-8">
            <Suspense fallback={<div className="text-center">Loading...</div>}>
                <DinSuccessContent />
            </Suspense>
        </div>
    )
}
